            for c in range(c1, c2 + 1):
                set_cell(r, c, ch)

    def advance_strip():
        for c in range(64):
            if board[63][c] == 'W':
                board[63][c] = 'p'
                return

    # Simple phase detection based on visible board features
    if action == 'LEFT':
        # Setup: clear right area, place purple/yellow blocks, reset strip
        set_rect(0, 17, 37, 53, 'S')
        for r in range(7, 11):
            for c in (14, 20, 26):
                set_cell(r, c, 'p')
                set_cell(r, c + 1, 'p')
                set_cell(r, c + 2, 'p')
        for c in (14, 20, 26):
            set_cell(11, c, 'Y')
            set_cell(11, c + 1, 'W')
            set_cell(11, c + 2, 'Y')
        set_rect(13, 17, 13, 29, 'S')
        for c in range(64):
            board[63][c] = 'W'
        return [''.join(row) for row in board]

    if action == 'RESET':
        return predict(board_lines, 'LEFT')

    if action.startswith('MOUSE'):
        parts = action.replace('MOUSE(', '').replace(')', '').split(',')
        r, c = int(parts[0]), int(parts[1])
        # Clear the 5x5 block under the click
        set_rect(r - 2, r + 2, c - 2, c + 2, 'S')
        advance_strip()
        return [''.join(row) for row in board]

    if action == 'RIGHT':
        # Move the small blue/yellow block right by 6 columns
        # Find the block's current left column
        left = None
        for c in range(13, 48):
            if board[37][c] in ('b', 'Y', 'P') and board[37][c + 1] in ('b', 'Y', 'P'):
                left = c
                break
        if left is None:
            # Large trigger transformation
            set_rect(0, 17, 37, 53, 'B')
            set_rect(13, 17, 30, 36, 'S')
            set_rect(18, 23, 13, 53, 'B')
            set_rect(24, 29, 13, 53, 'S')
            set_rect(37, 41, 37, 41, 'S')
            advance_strip()
            return [''.join(row) for row in board]

        new_left = left + 6
        for r in range(37, 42):
            for c in range(left, left + 5):
                set_cell(r, c, 'S')
        for r in range(37, 42):
            for c in range(new_left, new_left + 5):
                if r == 37:
                    val = 'B' if c in (new_left, new_left + 1, new_left + 3, new_left + 4) else 'b'
                elif r in (38, 39):
                    val = 'B' if c in (new_left, new_left + 4) else ('Y' if c == new_left + 3 else 'b')
                elif r == 40:
                    val = 'B' if c in (new_left, new_left + 1, new_left + 3, new_left + 4) else 'b'
                else:
                    val = 'B' if c in (new_left + 1, new_left + 2, new_left + 3) else 'S'
                set_cell(r, c, val)
        advance_strip()
        return [''.join(row) for row in board]

    return board_lines
