## world_model.md

1. The board is a 64×64 grid. The starting board is a schematic: `p` marks terrain to be revealed, `O`/`r` mark areas that become empty, `c` marks walls, and `N`/`W` are decorative markers, not the real player.
2. The first arrow action reveals the true level. The real player is a 3×3 block:
   ```
   NNN
   NWN
   NNN
   ```
   It starts at rows 48–50, columns 48–50 before the first move.
3. Arrow actions move the whole player block exactly 3 cells in that direction. If the destination is outside the board or blocked by a wall (`c`), the player does not move.
4. There are two groups of red hazard rows:
   - Upper group: rows 15–19, columns 24–29 and 33–38.
   - Lower group: rows 46–50, columns 42–47.
5. Each arrow action advances a red-cycle counter. When the counter is `k` (1–5), row `14+k` in the upper group and row `51-k` in the lower group change from red (`r`) to safe orange (`O`). After the 5th move, all orange cells become red again and the counter resets to 0.
6. The bottom row is a timer. Some actions consume the rightmost remaining charcoal (`c`) cell, changing it to white (`W`).
7. `MOUSE(row,col)` does not move the player; it only consumes one timer cell.
8. The goal is to navigate the player through the level while avoiding red hazards and collecting yellow (`Y`) items.

```python
def predict(board_lines, action):
    """
    Predict the complete next board after an action.
    Pure Python 3, deterministic, fast.
    """
    board = [list(row) for row in board_lines]

    # ------------------------------------------------------------
    # Helpers
    # ------------------------------------------------------------
    def is_schematic(b):
        # The schematic has purple markers at row 9, column 18.
        return len(b) > 9 and b[9][18] == 'p'

    def find_player(b):
        for r in range(62):
            for c in range(62):
                if (b[r][c] == 'N' and b[r][c+1] == 'N' and b[r][c+2] == 'N' and
                    b[r+1][c] == 'N' and b[r+1][c+1] == 'W' and b[r+1][c+2] == 'N' and
                    b[r+2][c] == 'N' and b[r+2][c+1] == 'N' and b[r+2][c+2] == 'N'):
                    return r, c
        return None

    def clear_player(b, r, c):
        for dr in range(3):
            for dc in range(3):
                b[r+dr][c+dc] = 'w'

    def place_player(b, r, c):
        for dr in range(3):
            for dc in range(3):
                b[r+dr][c+dc] = 'N'
        b[r+1][c+1] = 'W'

    def build_revealed_board():
        """Construct the revealed board from the schematic and known changes."""
        # Start from the schematic board.
        b = [list(row) for row in board_lines]

        # Apply the known reveal changes (from transition 0).
        # Row 0
        for c in range(64):
            b[0][c] = 'g'

        # Row 1
        b[1][0] = 'g'
        b[1][30] = b[1][31] = b[1][32] = 'g'
        b[1][63] = 'g'

        # Row 2
        b[2][0] = 'g'
        for c in range(5, 10):
            b[2][c] = 'c'
        b[2][30] = b[2][31] = b[2][32] = 'g'
        b[2][63] = 'g'

        # Rows 3-6
        for r in range(3, 7):
            b[r][0] = 'g'
            b[r][5] = 'c'
            b[r][9] = 'c'
            for c in range(24, 30):
                b[r][c] = 'w'
            b[r][30] = b[r][31] = b[r][32] = 'g'
            b[r][63] = 'g'

        # Rows 7-8
        for r in range(7, 9):
            b[r][0] = 'g'
            b[r][2] = 'c'
            b[r][12] = 'c'
            for c in range(24, 30):
                b[r][c] = 'w'
            b[r][30] = b[r][31] = b[r][32] = 'g'
            b[r][63] = 'g'

        # Rows 9-11
        for r in range(9, 12):
            b[r][0] = 'g'
            for c in range(2, 6):
                b[r][c] = 'c'
            for c in range(9, 13):
                b[r][c] = 'c'
            for c in range(18, 30):
                b[r][c] = 'w'
            b[r][30] = b[r][31] = b[r][32] = 'g'
            for c in range(33, 36):
                b[r][c] = 'w'
            b[r][63] = 'g'

        # Row 12
        b[12][0] = 'g'
        for c in range(5, 10):
            b[12][c] = 'c'
        for c in range(18, 21):
            b[12][c] = 'w'
        for c in range(21, 42):
            b[12][c] = 'g'
        b[12][63] = 'g'

        # Rows 13-14
        for r in range(13, 15):
            b[r][0] = 'g'
            for c in range(18, 21):
                b[r][c] = 'w'
            for c in range(21, 42):
                b[r][c] = 'g'
            b[r][63] = 'g'

        # Rows 15-19 (upper red hazards and yellow items)
        for r in range(15, 20):
            b[r][0] = 'g'
            if r == 18:
                for c in range(6, 15):
                    b[r][c] = 'Y'
            else:
                for c in range(9, 12):
                    b[r][c] = 'Y'
            for c in range(18, 21):
                b[r][c] = 'w'
            for c in range(21, 24):
                b[r][c] = 'g'
            for c in range(24, 30):
                b[r][c] = 'r'
            for c in range(30, 33):
                b[r][c] = 'g'
            for c in range(33, 39):
                b[r][c] = 'r'
            for c in range(39, 42):
                b[r][c] = 'g'
            b[r][63] = 'g'

        # Row 20
        b[20][0] = 'g'
        for c in range(18, 21):
            b[20][c] = 'w'
        for c in range(21, 36):
            b[20][c] = 'g'
        b[20][63] = 'g'

        # Rows 21-26: mostly empty
        for r in range(21, 27):
            b[r][0] = 'g'
            b[r][63] = 'g'

        # Rows 27-45: convert purple bars to floor, keep other cells empty
        for r in range(27, 46):
            b[r][0] = 'g'
            b[r][21] = b[r][22] = b[r][23] = 'g'
            b[r][30] = b[r][31] = b[r][32] = 'g'
            b[r][63] = 'g'

        # Row 30 has a wall at columns 45-49
        b[30][45] = b[30][46] = b[30][47] = b[30][48] = b[30][49] = 'c'

        # Rows 46-50: lower red hazards
        for r in range(46, 51):
            b[r][0] = 'g'
            b[r][21] = b[r][22] = b[r][23] = 'g'
            b[r][30] = b[r][31] = b[r][32] = 'g'
            for c in range(42, 48):
                b[r][c] = 'r'
            b[r][63] = 'g'

        # Rows 51-54
        for r in range(51, 55):
            b[r][0] = 'g'
            b[r][21] = b[r][22] = b[r][23] = 'g'
            b[r][30] = b[r][31] = b[r][32] = 'g'
            b[r][63] = 'g'

        # Rows 55-57: purple bar becomes floor
        for r in range(55, 58):
            b[r][0] = 'g'
            for c in range(21, 33):
                b[r][c] = 'g'
            b[r][63] = 'g'

        # Rows 58-62
        for r in range(58, 63):
            b[r][0] = 'g'
            b[r][63] = 'g'

        # Bottom row is already the timer.

        # Place the real player at the default start position.
        place_player(b, 48, 48)
        return b

    # ------------------------------------------------------------
    # Reveal if the board is still schematic
    # ------------------------------------------------------------
    if is_schematic(board):
        board = build_revealed_board()

    # ------------------------------------------------------------
    # Apply action
    # ------------------------------------------------------------
    if action in ("UP", "DOWN", "LEFT", "RIGHT"):
        pos = find_player(board)
        if pos is None:
            return board_lines
        pr, pc = pos

        if action == "UP":
            npr, npc = pr - 3, pc
        elif action == "DOWN":
            npr, npc = pr + 3, pc
        elif action == "LEFT":
            npr, npc = pr, pc - 3
        else:  # RIGHT
            npr, npc = pr, pc + 3

        # Move only if destination is inside the board and not a wall.
        can_move = True
        if not (0 <= npr <= 61 and 0 <= npc <= 61):
            can_move = False
        else:
            for dr in range(3):
                for dc in range(3):
                    if board[npr+dr][npc+dc] == 'c':
                        can_move = False

        if can_move:
            clear_player(board, pr, pc)
            place_player(board, npr, npc)

        # Red cycle.
        # Count consecutive orange rows in the upper group.
        cnt = 0
        for i in range(5):
            if board[15 + i][24] == 'O':
                cnt += 1
            else:
                break

        if cnt == 5:
            # Reset all orange to red.
            for r in range(15, 20):
                for c in list(range(24, 30)) + list(range(33, 39)):
                    if board[r][c] == 'O':
                        board[r][c] = 'r'
            for r in range(46, 51):
                for c in range(42, 48):
                    if board[r][c] == 'O':
                        board[r][c] = 'r'
        else:
            # Activate the next row in each group.
            r_upper = 15 + cnt
            r_lower = 50 - cnt
            for c in list(range(24, 30)) + list(range(33, 39)):
                if board[r_upper][c] == 'r':
                    board[r_upper][c] = 'O'
            for c in range(42, 48):
                if board[r_lower][c] == 'r':
                    board[r_lower][c] = 'O'

        # Timer: consume the rightmost remaining charcoal cell.
        for c in range(63, -1, -1):
            if board[63][c] == 'c':
                board[63][c] = 'W'
                break

    elif action.startswith("MOUSE"):
        # Mouse action only consumes one timer cell.
        for c in range(63, -1, -1):
            if board[63][c] == 'c':
                board[63][c] = 'W'
                break

    # UNDO and SPACE are not present in recorded transitions; treat as no-op.
    return [''.join(row) for row in board]
